import { SoundController } from './sound-controller';
import { SoundInstance } from './sound-instance';
import { ICrossfadeOptions, ICrossFadeResponse, IDynamicSoundOptions, IFadeOptions, ISoundPlayOptions } from './types';

export class SoundGroupController {

    protected readonly category: string;

    public constructor(protected controller: SoundController, options: {
        category: string;
        playbackOptions: ISoundPlayOptions
    }) {
        this.category = options.category;
        this.controller.createDefaultCategoryOptions(this.category, options.playbackOptions);
    }

    public set muted(value: boolean) {
        this.controller.setCategoryMuted(this.category, value);
    }

    public get muted(): boolean {
        return this.controller.getCategoryMuted(this.category);
    }

    public setVolume(volume: number): void {
        this.controller.setCategoryVolume(this.category, volume);
    }

    protected getActiveTracks(): SoundInstance[] {
        return this.controller.getActiveTracksOfCategory(this.category);
    }

    public fade(id: number, options?: Partial<IFadeOptions>): gsap.core.Timeline | undefined {
        return this.controller.fade(id, options);
    }

    public mute(): void {
        this.muted = true;
    }

    public unmute(): void {
        this.muted = false;
    }

    public pauseAll(): void {
        this.getActiveTracks()
            .forEach((instance) => {
                instance.pause();
            });
    }

    public resumeAll(): void {
        this.getActiveTracks()
            .forEach((instance) => {
                instance.resume();
            });
    }

    public stopAll(): void {
        this.controller.stopAllInCategory(this.category);
    }

    public resume(id: number): void {
        this.getInstance(id)?.resume();
    }

    public resumeAllInstancesOf(name: string, sprite?: string): void {
        this.getAllInstancesOf(name, sprite).forEach((instance) => {
            instance.resume();
        });
    }

    public pause(id: number): void {
        this.getInstance(id)?.pause();
    }

    public pauseAllInstancesOf(name: string, sprite?: string): void {
        this.getAllInstancesOf(name, sprite).forEach((instance) => {
            instance.pause();
        });
    }

    public seek(id: number, start: number): void {
        const instance = this.getInstance(id);
        if (instance) {
            instance.seek = start;
        }
    }

    /**
     * Gets the mediaInstance of the given track ID
     * @param id the unique id to retrieve
     * @returns { SoundInstance } the soundInstance
     */
    public getInstance(id: number): SoundInstance | undefined {
        const instance = this.controller.getInstance(id);
        if (instance?.category === this.category) {
            return instance;
        }
    }

    public getAllInstancesOf(name: string, sprite?: string): SoundInstance[] {
        return this.controller.getAllInstancesOf(name, sprite)
            .filter((instance) => instance.category === this.category);
    }

    /**
     * stops a given track id and cleans it up from the active list
     * @param id the id of the track to stop
     */
    public stop(id: number): void {
        this.getInstance(id)?.stop();
    }

    public stopAllInstancesOf(name: string, sprite?: string): void {
        this.getAllInstancesOf(name, sprite)
            .forEach((instance) => {
                instance.stop();
            });
    }

    public exists(name: string, sprite?: string): boolean {
        return this.controller.exists(name, sprite);
    }

    public play(name: string, options: ISoundPlayOptions = {}): SoundInstance | undefined {
        return this.controller.play(name, {
            ...options,
            category: this.category,
        });
    }

    /**
     * Removes all references of the passed sound from the activeList
     * @param key the name of the track to release
     */
    public releaseSound(name: string, sprite?: string): void {
        this.controller.getAllInstancesOf(name, sprite)
            .filter((instance) => instance.category === this.category)
            .forEach((instance) => {
                instance.dispose();
            });
    }

    public playDynamic(trackNames: string[], options?: Partial<IDynamicSoundOptions>): void {
        return this.controller.playDynamic(this.category, trackNames, options);
    }

    public stopDynamic(): void {
        return this.controller.stopDynamic(this.category);
    }

    public getCurrentDynamicTrack(): SoundInstance | undefined {
        return this.controller.getCurrentDynamicTrack(this.category);
    }

    public crossfade(fromSound: SoundInstance | number, toSound: { name: string, options?: Pick<ISoundPlayOptions, 'sprite'> }, options?: Partial<ICrossfadeOptions>): ICrossFadeResponse | void {
        return this.controller.crossfade(fromSound, { ...toSound, options: { ...toSound.options, category: this.category } }, options);
    }
}